CREATE TABLE members (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, phone TEXT, role TEXT NOT NULL DEFAULT 'member', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE accounts (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES members(id), name TEXT NOT NULL, institution TEXT NOT NULL DEFAULT 'Indian Bank', masked_number TEXT, opening_balance_paise INTEGER NOT NULL DEFAULT 0, opening_date TEXT, balance_paise INTEGER NOT NULL DEFAULT 0, balance_as_of TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE transactions (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES members(id), account_id TEXT NOT NULL REFERENCES accounts(id), date TEXT NOT NULL, description TEXT NOT NULL, amount_paise INTEGER NOT NULL, category TEXT NOT NULL, kind TEXT NOT NULL, balance_paise INTEGER, document_id TEXT, source_ref TEXT, fingerprint TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX idx_transactions_fingerprint ON transactions(account_id, fingerprint) WHERE fingerprint IS NOT NULL;
CREATE INDEX idx_transactions_account_date ON transactions(account_id, date);
CREATE TABLE investments (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES members(id), type TEXT NOT NULL, name TEXT NOT NULL, symbol TEXT, institution TEXT, principal_paise INTEGER, rate_bps INTEGER, start_date TEXT, maturity_date TEXT, maturity_amount_paise INTEGER, document_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE investment_snapshots (id TEXT PRIMARY KEY, investment_id TEXT NOT NULL REFERENCES investments(id), as_of TEXT NOT NULL, quantity TEXT, invested_paise INTEGER NOT NULL, value_paise INTEGER NOT NULL, document_id TEXT, source_ref TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(investment_id, as_of, source_ref));
CREATE TABLE payments (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES members(id), title TEXT NOT NULL, amount_paise INTEGER NOT NULL, next_due_date TEXT NOT NULL, frequency TEXT NOT NULL DEFAULT 'once', account_id TEXT, remind_days INTEGER NOT NULL DEFAULT 3, email_enabled INTEGER NOT NULL DEFAULT 1, sms_enabled INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payment_occurrences (id TEXT PRIMARY KEY, payment_id TEXT NOT NULL REFERENCES payments(id), due_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'due', paid_at TEXT, transaction_id TEXT, UNIQUE(payment_id, due_date));
CREATE TABLE documents (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES members(id), type TEXT NOT NULL, name TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, storage_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'uploaded', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE imports (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES members(id), document_id TEXT NOT NULL REFERENCES documents(id), target_id TEXT, type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, committed_at TEXT);
CREATE TABLE shares (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES members(id), recipient_id TEXT NOT NULL REFERENCES members(id), resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, permission TEXT NOT NULL DEFAULT 'view', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(recipient_id, resource_type, resource_id));
CREATE INDEX idx_shares_recipient ON shares(recipient_id, resource_type);
CREATE TABLE audit_log (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES members(id), action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT, detail_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reminder_deliveries (id TEXT PRIMARY KEY, payment_id TEXT NOT NULL REFERENCES payments(id), due_date TEXT NOT NULL, channel TEXT NOT NULL, recipient_id TEXT NOT NULL REFERENCES members(id), status TEXT NOT NULL, provider_id TEXT, error TEXT, attempted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(payment_id, due_date, channel, recipient_id));
